#!/usr/bin/env bash
# Contenu éditorial : texte riche assaini par liste blanche (un seul rendu HTML), présentation
# d'instructeur bornée à l'espace et à l'avatar de son auteur, lecture tolérante bloc par bloc.
# Prérequis : apply-fix-compensation.sh. Aucune migration. Usage (racine du repo) : bash apply-fix-contenu.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"packages/contracts/src/page/blocks.v1.ts" 2>/dev/null | grep -qF "richTextContentSchema"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "rewriteAssetPaths" "packages/backend/src/modules/storage/mediaPaths.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-compensation.sh"; exit 1; }
